const http = require('http');
const fs = require('fs');
const path = require('path');

const URL = 'http://127.0.0.1:54008/status';
const OUT = path.join(__dirname, 'results', 'status.json');

function writeStatus(status) {
  fs.mkdirSync(path.dirname(OUT), { recursive: true });
  fs.writeFileSync(OUT, JSON.stringify({ status }, null, 2) + '\n');
}

function writeError(err) {
  fs.mkdirSync(path.dirname(OUT), { recursive: true });
  fs.writeFileSync(
    OUT,
    JSON.stringify({ status: null, message: String(err && err.message || err) }, null, 2) + '\n'
  );
}

const req = http.get(URL, (res) => {
  res.on('data', () => {});
  res.on('end', () => {
    writeStatus(res.statusCode);
    console.log(`status=${res.statusCode} written to ${OUT}`);
  });
});

req.on('error', (err) => {
  writeError(err);
  console.error(`request failed: ${err.message}; recorded error to ${OUT}`);
  process.exitCode = 1;
});

req.setTimeout(5000, () => {
  req.destroy(new Error('timeout after 5000ms'));
});

